using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.SceneManagement;

// Real source geometry only. There is deliberately NO fallback cube, primitive,
// substituted building or autogenerated replacement for the user's gym.
public static class BraxhornOriginalGymImport
{
    private const string SourceModel = "Assets/Source/braxhorn-original-gym.glb";
    private const string Collisions = "Assets/Source/gym-collisions.json";
    private const string ResultScene = "Assets/Generated/OriginalGym.unity";

    [Serializable] private sealed class SourceWorld
    {
        public SourceBox[] boxes;
        public SourceCircle[] circles;
    }

    [Serializable] private sealed class SourceBox
    {
        public float minX, maxX, minZ, maxZ, top, bottom;
        public string tag;
    }

    [Serializable] private sealed class SourceCircle
    {
        public float x, z, r, top, bottom;
        public string tag;
        public bool noStand;
    }

    [MenuItem("Braxhorn City/Import original gym (NO fallback assets)")]
    public static void Import()
    {
        if (!File.Exists(SourceModel) || !File.Exists(Collisions))
            throw new InvalidOperationException(
                "Missing real source gym export. Run the protected export workflow. Do NOT make placeholder geometry.");

        AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);
        GameObject original = AssetDatabase.LoadAssetAtPath<GameObject>(SourceModel);
        if (original == null)
            original = AssetDatabase.LoadAllAssetsAtPath(SourceModel).OfType<GameObject>().FirstOrDefault();
        if (original == null)
            throw new InvalidOperationException(
                "glTFast did not import the original gym .glb as a GameObject. No fake scene will be generated.");

        SourceWorld physics = JsonUtility.FromJson<SourceWorld>(File.ReadAllText(Collisions));
        if (physics == null || physics.boxes == null || physics.boxes.Length < 10)
            throw new InvalidOperationException("Source collision data missing or truncated.");

        Scene scene = EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        GameObject gym = PrefabUtility.InstantiatePrefab(original) as GameObject;
        if (gym == null) gym = UnityEngine.Object.Instantiate(original);
        gym.name = "BRAXHORN CITY - ORIGINAL GYM (SOURCE GEOMETRY)";
        gym.transform.SetPositionAndRotation(Vector3.zero, Quaternion.identity);
        gym.transform.localScale = Vector3.one;

        int meshCount = gym.GetComponentsInChildren<MeshFilter>(true).Length;
        if (meshCount < 20)
            throw new InvalidOperationException("Imported gym geometry is unexpectedly small; refusing substitution.");

        GameObject solids = new GameObject("Original physics colliders - invisible");
        int boxCount = 0;
        foreach (var b in physics.boxes)
        {
            if (b.maxX <= b.minX || b.maxZ <= b.minZ || b.top <= b.bottom) continue;
            GameObject o = new GameObject("World box " + boxCount + " " + (b.tag ?? ""));
            o.transform.SetParent(solids.transform, false);
            o.transform.position = new Vector3((b.minX + b.maxX) * .5f, (b.top + b.bottom) * .5f,
                (b.minZ + b.maxZ) * .5f);
            BoxCollider c = o.AddComponent<BoxCollider>();
            c.size = new Vector3(b.maxX - b.minX, b.top - b.bottom, b.maxZ - b.minZ);
            boxCount++;
        }

        if (physics.circles != null)
            foreach (var p in physics.circles)
            {
                if (p.r <= 0 || p.top <= p.bottom) continue;
                GameObject o = new GameObject("World cylinder " + (p.tag ?? ""));
                o.transform.SetParent(solids.transform, false);
                o.transform.position = new Vector3(p.x, (p.top + p.bottom) * .5f, p.z);
                CapsuleCollider c = o.AddComponent<CapsuleCollider>();
                c.direction = 1;
                c.radius = p.r;
                c.height = Mathf.Max(p.top - p.bottom, 2f * p.r);
            }

        // The browser world uses groundAt(y=0) even with no physical floor mesh collider.
        // Add invisible collision surfaces at the EXACT gymfloor.js floor coordinates.
        AddFloor(solids.transform, "Original hall floor", 0f, -2.5f, 37.2f, 28.2f);
        AddFloor(solids.transform, "Original alley floor", -6.75f, 16.4f, 16.7f, 9.6f);

        Camera camera = new GameObject("Visual comparison camera - manual scene preview").AddComponent<Camera>();
        camera.tag = "MainCamera";
        camera.transform.position = new Vector3(-11f, 3.2f, 3.5f);
        camera.transform.LookAt(new Vector3(1f, 2.3f, -3f));
        camera.fieldOfView = 55f;
        camera.clearFlags = CameraClearFlags.SolidColor;
        camera.backgroundColor = new Color(.07f, .08f, .085f);

        var light = new GameObject("Matte ambient preview light").AddComponent<Light>();
        light.type = LightType.Directional;
        light.transform.rotation = Quaternion.Euler(50f, -50f, 0f);
        light.intensity = .7f;
        RenderSettings.ambientLight = new Color(.35f, .35f, .35f);
        RenderSettings.fog = false;

        Directory.CreateDirectory("Assets/Generated");
        if (!EditorSceneManager.SaveScene(scene, ResultScene))
            throw new IOException("Could not save imported gym scene.");
        EditorBuildSettings.scenes = new[] { new EditorBuildSettingsScene(ResultScene, true) };
        AssetDatabase.SaveAssets();
        Debug.Log("ORIGINAL_GYM_SCENE_IMPORTED: meshes=" + meshCount + " colliders=" + boxCount +
                  ". NOT PLAYABLE YET. Must import actual Brax/Nyxa rigs and test mobile controls.");
    }

    private static void AddFloor(Transform parent, string name, float cx, float cz, float sx, float sz)
    {
        GameObject o = new GameObject(name);
        o.transform.SetParent(parent, false);
        o.transform.position = new Vector3(cx, -.10f, cz);
        o.AddComponent<BoxCollider>().size = new Vector3(sx, .20f, sz);
    }
}
